import{createHash}from"node:crypto";export function buildGovernanceEvidenceBundleReplay({manifestHash,completenessHash,environmentHash,resultHash}){for(let h of[manifestHash,completenessHash,environmentHash,resultHash])if(!/^[a-f0-9]{64}$/.test(h||""))throw Error("replay invalid");let b={kind:"governance-evidence-bundle-replay/v1",manifestHash,completenessHash,environmentHash,resultHash};return Object.freeze({...b,replayHash:createHash("sha256").update(JSON.stringify(b)).digest("hex")})}
